test({ sr: 'uspeva iz prvog pokušaja', en: 'succeeds on the first attempt' }, async () => {
  let calls = 0;
  const result = await retry(async () => { calls++; return 'ok'; }, 3);
  expect(result).toBe('ok');
  expect(calls).toBe(1);
});
test({ sr: 'ponavlja dok ne uspe', en: 'retries until it succeeds' }, async () => {
  let calls = 0;
  const result = await retry(async () => {
    calls++;
    if (calls < 3) throw new Error('not yet');
    return 'done';
  }, 5);
  expect(result).toBe('done');
  expect(calls).toBe(3);
});
test({ sr: 'odbija se poslednjom greškom', en: 'rejects with the last error' }, async () => {
  let calls = 0;
  await expect(retry(async () => { calls++; throw new Error('fail ' + calls); }, 3)).rejects.toThrow('fail 3');
  expect(calls).toBe(3);
});

